// Forfeit Skies Mod Book (Patchouli book "patchouli:mods": patchouli_books/mods/book.json + kubejs/assets/patchouli/...,
// generated by docs/guide-tools/build-modbook.mjs).
// Every player gets one copy the first time they join; lost it? Craft a book + compass.
const MOD_BOOK = 'patchouli:guide_book[patchouli:book="patchouli:mods"]'
const GIVEN_FLAG = 'forfeit_got_modbook_v2'   // v2: the first version used a book id Patchouli couldn't load

PlayerEvents.loggedIn(event => {
  const player = event.player
  if (!player.persistentData.getBoolean(GIVEN_FLAG)) {
    player.give(Item.of(MOD_BOOK))
    player.persistentData.putBoolean(GIVEN_FLAG, true)
    player.tell(Text.of('[Forfeit Skies] ').darkPurple().append(Text.of('Here is the Mod Book: every mod in the pack, grouped by type.').gray()))
  }
})

ServerEvents.recipes(event => {
  event.shapeless(Item.of(MOD_BOOK), ['minecraft:book', 'minecraft:compass']).id('forfeit:mod_book')
})
